defense.sentinel_kql:
let anon = _GetWatchlist("none");
Syslog
| where SyslogMessage has_any ("kubeletctl",":10250","system:anonymous")
| project TimeGenerated, Computer, SyslogMessage
| sort by TimeGenerated desc
// anonymous Kubelet/API access on 10250/6443 from outside the cluster

